-- EJECUTAR SOLO EN UNA BASE DE DATOS NUEVA.
-- Si ya creaste las 13 tablas con el diagrama ER, NO vuelvas a ejecutar este archivo.
CREATE TABLE rol (id_rol SERIAL PRIMARY KEY, nombre VARCHAR(50) UNIQUE NOT NULL);
CREATE TABLE usuario (id_usuario SERIAL PRIMARY KEY,id_rol INTEGER NOT NULL REFERENCES rol(id_rol),nombre VARCHAR(100) NOT NULL,correo VARCHAR(150) UNIQUE NOT NULL,hash_contrasena VARCHAR(255) NOT NULL,estado BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE turno_caja (id_turno SERIAL PRIMARY KEY,id_usuario INTEGER NOT NULL REFERENCES usuario(id_usuario),apertura TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,cierre TIMESTAMP,estado VARCHAR(20) NOT NULL DEFAULT 'ABIERTO',fondo_inicial NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK(fondo_inicial>=0),efectivo_contado NUMERIC(12,2) CHECK(efectivo_contado>=0));
CREATE TABLE movimiento_caja (id_movimiento_caja SERIAL PRIMARY KEY,id_turno INTEGER NOT NULL REFERENCES turno_caja(id_turno),fecha_hora TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,tipo VARCHAR(20) NOT NULL CHECK(tipo IN ('INGRESO','EGRESO')),concepto VARCHAR(255) NOT NULL,monto NUMERIC(12,2) NOT NULL CHECK(monto>0));
CREATE TABLE cliente (id_cliente SERIAL PRIMARY KEY,nombre_razon_social VARCHAR(150) NOT NULL,nit_dpi VARCHAR(30),telefono VARCHAR(20),correo VARCHAR(150),direccion_fiscal TEXT);
CREATE TABLE categoria (id_categoria SERIAL PRIMARY KEY,nombre VARCHAR(100) UNIQUE NOT NULL,descripcion TEXT);
CREATE TABLE producto (id_producto SERIAL PRIMARY KEY,id_categoria INTEGER NOT NULL REFERENCES categoria(id_categoria),codigo VARCHAR(50) UNIQUE NOT NULL,codigo_barras VARCHAR(100) UNIQUE,nombre VARCHAR(150) NOT NULL,marca VARCHAR(100),unidad VARCHAR(30) NOT NULL,costo NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK(costo>=0),precio_venta NUMERIC(12,2) NOT NULL CHECK(precio_venta>=0),stock_minimo INTEGER NOT NULL DEFAULT 5 CHECK(stock_minimo>=0),estado BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE proveedor (id_proveedor SERIAL PRIMARY KEY,razon_social VARCHAR(150) NOT NULL,nit VARCHAR(30),contacto VARCHAR(100),telefono VARCHAR(20),correo VARCHAR(150),direccion TEXT);
CREATE TABLE venta (id_venta SERIAL PRIMARY KEY,id_cliente INTEGER NOT NULL REFERENCES cliente(id_cliente),id_usuario INTEGER NOT NULL REFERENCES usuario(id_usuario),id_turno INTEGER NOT NULL REFERENCES turno_caja(id_turno),numero_ticket VARCHAR(50) UNIQUE NOT NULL,fecha_hora TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,metodo_pago VARCHAR(30) NOT NULL,estado VARCHAR(20) NOT NULL DEFAULT 'COMPLETADA',total NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK(total>=0));
CREATE TABLE detalle_venta (id_detalle_venta SERIAL PRIMARY KEY,id_venta INTEGER NOT NULL REFERENCES venta(id_venta),id_producto INTEGER NOT NULL REFERENCES producto(id_producto),cantidad INTEGER NOT NULL CHECK(cantidad>0),precio_unitario NUMERIC(12,2) NOT NULL CHECK(precio_unitario>=0),costo_unitario_historico NUMERIC(12,2) NOT NULL CHECK(costo_unitario_historico>=0),descuento NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK(descuento>=0),tasa_iva NUMERIC(5,2) NOT NULL DEFAULT 12.00 CHECK(tasa_iva>=0));
CREATE TABLE compra (id_compra SERIAL PRIMARY KEY,id_proveedor INTEGER NOT NULL REFERENCES proveedor(id_proveedor),id_usuario INTEGER NOT NULL REFERENCES usuario(id_usuario),numero_factura VARCHAR(50),fecha TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,metodo_pago VARCHAR(30) NOT NULL,total NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK(total>=0));
CREATE TABLE detalle_compra (id_detalle_compra SERIAL PRIMARY KEY,id_compra INTEGER NOT NULL REFERENCES compra(id_compra),id_producto INTEGER NOT NULL REFERENCES producto(id_producto),cantidad INTEGER NOT NULL CHECK(cantidad>0),costo_unitario NUMERIC(12,2) NOT NULL CHECK(costo_unitario>=0));
CREATE TABLE movimiento_inventario (id_movimiento_inventario SERIAL PRIMARY KEY,id_producto INTEGER NOT NULL REFERENCES producto(id_producto),fecha_hora TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,tipo VARCHAR(20) NOT NULL CHECK(tipo IN ('ENTRADA','SALIDA')),cantidad INTEGER NOT NULL CHECK(cantidad>0),costo_unitario NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK(costo_unitario>=0),motivo TEXT);
CREATE VIEW vista_inventario AS SELECT p.id_producto,p.codigo,p.nombre,p.precio_venta,p.stock_minimo,COALESCE(SUM(CASE WHEN mi.tipo='ENTRADA' THEN mi.cantidad WHEN mi.tipo='SALIDA' THEN -mi.cantidad ELSE 0 END),0) AS existencia_actual FROM producto p LEFT JOIN movimiento_inventario mi USING(id_producto) GROUP BY p.id_producto,p.codigo,p.nombre,p.precio_venta,p.stock_minimo;
